from collections import deque, Counter

def comps(mat, predicate, r0=0, r1=None, c0=0,c1=None):
    if r1 is None:r1=len(mat)
    if c1 is None:c1=len(mat[0])
    seen=set(); out=[]
    for r in range(r0,r1):
      for c in range(c0,c1):
        if (r,c) in seen or not predicate(mat[r][c]): continue
        q=[(r,c)];seen.add((r,c));cells=[]
        while q:
          rr,cc=q.pop();cells.append((rr,cc))
          for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
            nr,nc=rr+dr,cc+dc
            if r0<=nr<r1 and c0<=nc<c1 and (nr,nc) not in seen and predicate(mat[nr][nc]):
              seen.add((nr,nc));q.append((nr,nc))
        out.append(cells)
    return out

def comp_summary(cells, mat):
    rs=[r for r,c in cells]; cs=[c for r,c in cells]
    hist=Counter(mat[r][c] for r,c in cells)
    return (len(cells),(min(rs),min(cs),max(rs),max(cs)),dict(hist))
